    {
      "kr": "KR 2.1 — Blended CAC reduction",
      "owner": "Marcus Webb",
      "pace_ratio_or_progress": "55% at quarter close; pace ratio 0.55/1.0 = 0.55 — Off-track; inherits at-risk from KR 1.3 scope failure",
      "blocker_type": "External dependency (internal): DTC channel not live as planned; attribution efficiency benefit not realized",
      "what_would_unblock": "DTC checkout launch in Q3 per leadership decision on KR 1.3"
    },
    {
      "kr": "KR 3.2 — Stage-gate 2 advancement",
